    65	/// Atomically publish `bytes` to a `/dev/shm` path via a sibling temp file +
    66	/// rename, so readers see either the old or new content, never a torn write.
    67	fn atomic_write_shm(path: &str, bytes: &[u8]) -> Result<()> {
    68	    if let Some(parent) = std::path::Path::new(path).parent() {
    69	        std::fs::create_dir_all(parent)
    70	            .map_err(|e| anyhow::anyhow!("Cannot create {}: {}", parent.display(), e))?;
    71	    }
    72	    let tmp = format!("{}.tmp", path);
    73	    {
    74	        let mut file = std::fs::File::create(&tmp)
    75	            .map_err(|e| anyhow::anyhow!("Cannot create {}: {}", tmp, e))?;
    76	        file.write_all(bytes)
    77	            .map_err(|e| anyhow::anyhow!("Failed to write {}: {}", tmp, e))?;
    78	        file.sync_all()
    79	            .map_err(|e| anyhow::anyhow!("Failed to sync {}: {}", tmp, e))?;
    80	    }
    81	    std::fs::rename(&tmp, path)
    82	        .map_err(|e| anyhow::anyhow!("Failed to rename {} -> {}: {}", tmp, path, e))?;
    83	    Ok(())
    84	}
