   135	/// `blobify`, stamping the publishing account's WireGuard-keypair identity
   136	/// (public half only) into the manifest.
   137	pub fn blobify_with_identity(
   138	    schema: &PluginSchema,
   139	    identity: Option<crate::identity::BlobIdentity>,
   140	) -> PluginObjectBlob {
   141	    let plugin_id = canonical_plugin_id(&schema.name);
   142	    let schema_json = schema.canonical_json();
   143	    let schema_hash = {
   144	        let mut h = Sha256::new();
   145	        h.update(schema_json.as_bytes());
   146	        hex(&h.finalize())
   147	    };
   148	
   149	    let (descriptor_set, method_infos) = descriptor::descriptor_set_for_plugin(&plugin_id, schema);
   150	
   151	    let mut methods: Vec<MethodManifest> = method_infos
   152	        .iter()
   153	        .map(|d| {
   154	            let decl = &schema.methods[&d.method_name];
   155	            MethodManifest {
   156	                schema_name: decl.name.clone(),
   157	                grpc_name: descriptor::pascal_case(&decl.name),
   158	                grpc_path: d.grpc_path.clone(),
   159	                grpc_service: d.service_full.clone(),
   160	                grpc_file: d.file_name.clone(),
   161	                input_message: d.input_full.clone(),
   162	                output_message: d.output_full.clone(),
   163	                subid: decl.subid.clone(),
   164	                required_capability: decl.required_capability.clone(),
   165	                side_effect: decl.side_effect,
   166	                idempotent: decl.idempotent,
   167	                symbols: d.symbols.clone(),
   168	            }
   169	        })
   170	        .collect();
   171	    methods.sort_by(|a, b| a.schema_name.cmp(&b.schema_name));
   172	
   173	    let mut services: Vec<String> = methods.iter().map(|m| m.grpc_service.clone()).collect();
   174	    services.sort();
   175	    let mut files: Vec<String> = methods.iter().map(|m| m.grpc_file.clone()).collect();
   176	    files.sort();
   177	
   178	    let manifest = BlobManifest {
   179	        blob_type: default_blob_type(),
   180	        plugin_id: plugin_id.clone(),
   181	        schema_version: schema.version.clone(),
   182	        schema_hash,
   183	        dbus: DbusIdentity {
   184	            bus_name: "org.opdbus.v1.plugins".to_string(),
   185	            object_path: format!("/org/opdbus/v1/plugins/{plugin_id}"),
   186	            interface_name: "org.opdbus.v1.Plugin".to_string(),
   187	        },
   188	        grpc: GrpcIdentity { services, files },
   189	        identity,
   190	        methods,
   191	    };
   192	
   193	    let meta = serde_json::json!({
   194	        "blob_format": FORMAT_VERSION,
   195	        "dialect": schema.dialect,
   196	        "subids": schema.subids,
   197	        "immutable_paths": schema.immutable_paths,
   198	        "json_schema": schema.to_json_schema(),
   199	    });
   200	
   201	    PluginObjectBlob {
   202	        manifest,
   203	        schema_json,
   204	        descriptor_set,
   205	        meta_json: serde_json::to_string(&meta).expect("meta serializes"),
   206	    }
   207	}
