   209	impl PluginObjectBlob {
   210	    /// Seal into the immutable byte image. Deterministic: same schema, same bytes.
   211	    pub fn seal(&self) -> Vec<u8> {
   212	        let manifest_json =
   213	            serde_json::to_string(&serde_json::to_value(&self.manifest).unwrap()).unwrap();
   214	        let sections: [(u32, &[u8]); 4] = [
   215	            (SECTION_SCHEMA_JSON, self.schema_json.as_bytes()),
   216	            (SECTION_MANIFEST_JSON, manifest_json.as_bytes()),
   217	            (SECTION_DESCRIPTOR_SET, &self.descriptor_set),
   218	            (SECTION_META_JSON, self.meta_json.as_bytes()),
   219	        ];
   220	
   221	        let table_len = sections.len() * SECTION_ENTRY_LEN;
   222	        let mut offset = align8(HEADER_LEN + table_len);
   223	        let mut entries = Vec::with_capacity(sections.len());
   224	        for (tag, bytes) in &sections {
   225	            entries.push((*tag, offset as u64, bytes.len() as u64));
   226	            offset = align8(offset + bytes.len());
   227	        }
   228	
   229	        let mut out = Vec::with_capacity(offset);
   230	        out.extend_from_slice(MAGIC);
   231	        out.extend_from_slice(&FORMAT_VERSION.to_le_bytes());
   232	        out.extend_from_slice(&(sections.len() as u16).to_le_bytes());
   233	        out.extend_from_slice(&[0u8; 4]);
   234	        let mut h = Sha256::new();
   235	        h.update(self.schema_json.as_bytes());
   236	        out.extend_from_slice(&h.finalize());
   237	        out.extend_from_slice(&[0u8; 16]);
   238	        debug_assert_eq!(out.len(), HEADER_LEN);
   239	
   240	        for (tag, off, len) in &entries {
   241	            out.extend_from_slice(&tag.to_le_bytes());
   242	            out.extend_from_slice(&[0u8; 4]);
   243	            out.extend_from_slice(&off.to_le_bytes());
   244	            out.extend_from_slice(&len.to_le_bytes());
   245	        }
   246	
   247	        for ((_, bytes), (_, off, _)) in sections.iter().zip(&entries) {
   248	            while out.len() < *off as usize {
   249	                out.push(0);
   250	            }
   251	            out.extend_from_slice(bytes);
   252	        }
   253	        out
   254	    }
