    33	/// Lightweight shape check used to test whether a value satisfies one branch
    34	/// of a `FieldType::OneOf` discriminated union.
    35	fn value_matches_field_type(field_type: &FieldType, value: &Value) -> bool {
    36	    match (field_type, value) {
    37	        (FieldType::String, Value::String(_)) => true,
    38	        (FieldType::Integer, Value::Static(StaticNode::I64(_) | StaticNode::U64(_))) => true,
    39	        (FieldType::Float, Value::Static(StaticNode::F64(_))) => true,
    40	        (FieldType::Boolean, Value::Static(StaticNode::Bool(_))) => true,
    41	        (FieldType::Object(_), Value::Object(_)) => true,
    42	        (FieldType::Array(_), Value::Array(_)) => true,
    43	        (FieldType::Enum(values), Value::String(s)) => values.contains(&s.to_string()),
    44	        (FieldType::OneOf(branches), v) => branches
    45	            .iter()
    46	            .any(|branch| value_matches_field_type(branch, v)),
    47	        (FieldType::Any, _) => true,
    48	        _ => false,
    49	    }
