   277	/// Zero-copy view over sealed blob bytes. Construction verifies magic,
   278	/// bounds, and the schema hash once; accessors return borrowed slices.
   279	pub struct BlobRef<'a> {
   280	    bytes: &'a [u8],
   281	    sections: Vec<(u32, usize, usize)>,
   282	}
   283	
   284	impl<'a> BlobRef<'a> {
   285	    pub fn new(bytes: &'a [u8]) -> Result<Self, String> {
   286	        if bytes.len() < HEADER_LEN || &bytes[..8] != MAGIC {
   287	            return Err("not an OPBLOB01 blob".into());
   288	        }
   289	        let version = u16::from_le_bytes([bytes[8], bytes[9]]);
   290	        if version != FORMAT_VERSION {
   291	            return Err(format!("unsupported blob format version {version}"));
   292	        }
   293	        let count = u16::from_le_bytes([bytes[10], bytes[11]]) as usize;
   294	        let table_end = HEADER_LEN + count * SECTION_ENTRY_LEN;
   295	        if bytes.len() < table_end {
   296	            return Err("section table overruns blob".into());
   297	        }
   298	        let mut sections = Vec::with_capacity(count);
   299	        for i in 0..count {
   300	            let e = HEADER_LEN + i * SECTION_ENTRY_LEN;
   301	            let tag = u32::from_le_bytes(bytes[e..e + 4].try_into().unwrap());
   302	            let off = u64::from_le_bytes(bytes[e + 8..e + 16].try_into().unwrap()) as usize;
   303	            let len = u64::from_le_bytes(bytes[e + 16..e + 24].try_into().unwrap()) as usize;
   304	            if off + len > bytes.len() {
   305	                return Err(format!("section {tag} overruns blob"));
   306	            }
   307	            sections.push((tag, off, len));
   308	        }
   309	        let blob = Self { bytes, sections };
   310	
   311	        // Verify schema hash (blob-drift guard).
   312	        let schema = blob
   313	            .section(SECTION_SCHEMA_JSON)
   314	            .ok_or("missing schema section")?;
   315	        let mut h = Sha256::new();
   316	        h.update(schema);
   317	        if h.finalize().as_slice() != &bytes[16..48] {
   318	            return Err("schema hash mismatch: blob is corrupt or tampered".into());
   319	        }
   320	        Ok(blob)
   321	    }
